   188	import java.net.http.HttpRequest;
   189	import java.net.http.HttpResponse;
   190	import java.time.Duration;
   191	
   192	public class TransLogClient {
   193	    private static final Logger logger = LoggerFactory.getLogger(TransLogClient.class);
   194	    private static final ObjectMapper mapper = new ObjectMapper();
   195	    private static final HttpClient httpClient = HttpClient.newHttpClient();
   196	
   197	    public record ShippingQuote(BigDecimal price, int deliveryDays) {}
   198	
   199	    public static ShippingQuote quote(String zipCode, double weightKg, String service) throws CarrierUnavailableException {
   200	        String translogUrl = System.getenv("TRANSLOG_URL");
   201	        if (translogUrl == null) {
   202	            throw new CarrierUnavailableException();
   203	        }
   204	
   205	        int weightGrams = (int) Math.round(weightKg * 1000);
   206	        String url = String.format("%s/v2/quote?zip=%s&weight_g=%d&service=%s", translogUrl, zipCode, weightGrams, service);
   207	
   208	        try {
   209	            var request = HttpRequest.newBuilder()
   210	                .uri(URI.create(url))
   211	                .timeout(Duration.ofSeconds(2))
   212	                .GET()
   213	                .build();
   214	
   215	            var response = httpClient.send(request, HttpResponse.BodyHandlers.ofString());
   216	
   217	            if (response.statusCode() != 200) {
   218	                logger.warn("TransLog returned status {}", response.statusCode());
   219	                throw new CarrierUnavailableException();
   220	            }
   221	
   222	            JsonNode node = mapper.readTree(response.body());
   223	
   224	            if (node.has("error")) {
   225	                return null;
   226	            }
   227	
   228	            if (!node.has("price_cents") || !node.has("eta_hours")) {
   229	                throw new CarrierUnavailableException();
   230	            }
   231	
   232	            long priceCents = node.get("price_cents").asLong();
   233	            BigDecimal priceReais = Money.divide(new BigDecimal(priceCents), new BigDecimal("100"));
   234	
   235	            int hoursEta = node.get("eta_hours").asInt();
   236	            int deliveryDays = (int) Math.ceil((double) hoursEta / 24);
   237	
   238	            return new ShippingQuote(priceReais, deliveryDays);
   239	        } catch (IOException | InterruptedException e) {
   240	            logger.error("Failed to contact TransLog", e);
   241	            throw new CarrierUnavailableException();
   242	        }
   243	    }
   244	
   245	    public static class CarrierUnavailableException extends Exception {
   246	        public CarrierUnavailableException() {
   247	            super("Carrier unavailable");
   248	        }
   249	    }
   250	}
